INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 5, 'theory', 'Quiz: text and data protection');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 5, 0, 'How does a Unicode code point differ from the UTF-8 encoding?', '["It does not — they are the same thing", "A code point is a character''s number, UTF-8 is a way to write that number in bytes", "UTF-8 is a character''s number, a code point is a way of writing it", "A code point exists only for English letters"]', 1, 'Unicode assigns numbers to characters, while UTF-8, UTF-16 and others are ways to turn those numbers into bytes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 5, 1, 'How many bytes does the Russian letter «Ж» take in UTF-8?', '["One", "Two", "Three", "Four"]', 1, 'Code points U+0080…U+07FF are written with two bytes following the pattern 110xxxxx 10xxxxxx; for «Ж» this is D0 96.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 5, 2, 'Why is a simple sum of bytes a bad checksum?', '["It takes too long to compute", "It does not notice swapped bytes and errors that cancel each other out", "It works only for text", "It is always equal to zero"]', 1, 'Addition is commutative: if you swap two bytes, the sum does not change. CRC depends on the position of every bit.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 5, 3, 'What does the syndrome show in a Hamming (7,4) code?', '["The number of ones in the word", "The number of the flipped bit (0 — no errors)", "The checksum of the file", "The length of the word"]', 1, 'Three parity checks form a three-bit number — the position of the wrong bit; it is enough to flip it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 5, 4, 'What is CRC32 suitable for, and what is SHA-256 suitable for?', '["Both protect equally well against an attacker", "CRC32 — against random failures; SHA-256 — when protection against deliberate tampering is needed", "CRC32 — against tampering; SHA-256 — against failures", "Neither, they are obsolete"]', 1, 'A CRC is easy to forge to a desired value, so cryptographic hashes are used for security.');
